UPDATE mall_goods_spec
SET stock = stock - #{num}, frozen_stock = frozen_stock - #{num}
WHERE id = #{specId} AND frozen_stock >= #{num}

UPDATE mall_goods_spec
SET frozen_stock = frozen_stock + #{num}
WHERE id = #{specId} AND (stock - frozen_stock) >= #{num}

UPDATE mall_goods_spec
SET frozen_stock = frozen_stock - #{num}
WHERE id = #{specId} AND frozen_stock >= #{num}

UPDATE mall_goods_spec
SET stock = stock - #{num}
WHERE id = #{specId} AND stock >= #{num}
